   v='-('+z+')';xkey=round(g.mm(x),8);zkey=round(g.mm(v),8);p=g.skeleton_point(sk,x,v);g.point_dimensions(sk,p,None if xkey in xs else x,None if zkey in zs else v)
   if xkey in xs:sk.geometricConstraints.addVerticalPoints(xs[xkey],p)
